import * as s from "../core/validation/index.js";
import type { EnumSchema } from "../core/validation/schema.js";

/** Delivery types for assets generated by Cloudinary operations. */
export const GeneratedDeliveryType = {
  Multi: "multi",
  Sprite: "sprite",
  Text: "text",
  List: "list",
} as const;
export type GeneratedDeliveryType =
  | (typeof GeneratedDeliveryType)[keyof typeof GeneratedDeliveryType]
  | (string & {});

export const generatedDeliveryTypeSchema: EnumSchema<GeneratedDeliveryType> =
  s.enumOf<GeneratedDeliveryType>(GeneratedDeliveryType);
